  "Claudex will use your mouse and keyboard in {apps}.":
    "Claudex usará tu ratón y teclado en {apps}.",
  "the apps you allowed": "las aplicaciones que autorizaste",
  "Other apps will be hidden until it finishes.":
    "Las demás aplicaciones se ocultarán hasta que termine.",
  "Press Esc to stop at any time.":
    "Pulsa Esc en cualquier momento para detenerlo.",
  "Let Claudex see and act in the apps you allow, working in the background or with full control of your screen. Screenshots of those apps are sent to the model.":
    "Permite que Claudex vea y utilice las aplicaciones que autorices, en segundo plano o con control total de tu pantalla. Las capturas de pantalla de esas aplicaciones se envían al modelo.",
  "Background: Claudex works inside the apps you allow while you keep using your computer, and asks your permission before taking full control of your screen. Full control: Claudex takes control of your screen, mouse, and keyboard by default whenever Claudex uses an app you allow, without asking again.":
    "Segundo plano: Claudex trabaja en las aplicaciones autorizadas mientras sigues usando tu ordenador y pide permiso antes de tomar el control total de la pantalla. Control total: cuando usa una aplicación autorizada, Claudex toma por defecto el control de la pantalla, el ratón y el teclado, sin volver a preguntar.",
  "Claudex uses your computer's OpenSSH. Passwords are never saved; use an SSH key and ssh-agent to connect without prompts.":
    "Claudex usa OpenSSH de tu ordenador. Las contraseñas nunca se guardan; usa una clave SSH y ssh-agent para conectarte sin solicitudes de contraseña.",
  "Run Code sessions on another computer over SSH. Claudex uses this computer's OpenSSH and your SSH keys; passwords are never saved.":
    "Ejecuta sesiones de Code en otro ordenador mediante SSH. Claudex usa OpenSSH de este ordenador y tus claves SSH; las contraseñas nunca se guardan.",
  ".md file must contain skill name and description formatted in YAML":
    "El archivo .md debe contener el nombre y la descripción de la habilidad en formato YAML",
  ".zip or .skill file must include a SKILL.md file":
    "El archivo .zip o .skill debe incluir un archivo SKILL.md",
  "Claudex references the same knowledge every time you talk to it in this project.":
    "Claudex consulta los mismos conocimientos cada vez que conversas con él en este proyecto.",
  "Provide Claudex with relevant instructions and information for chats within {name}. This will work alongside your personal instructions and the selected style in a chat.":
    "Proporciona a Claudex instrucciones e información pertinentes para los chats en {name}. Se combinarán con tus instrucciones personales y el estilo seleccionado en el chat.",
