  "Added. It also uses {services}, which need signing in before Claudex can use them.":
    "Añadido. También utiliza {services}, donde debes iniciar sesión antes de que Claudex pueda usarlos.",
  "Make sure you trust a plugin before installing, updating, or using it. Plugins installed from marketplaces are not controlled by Anthropic, and Anthropic cannot verify that they will work as intended or that they won't change. See each plugin's homepage for more information.":
    "Asegúrate de confiar en un plugin antes de instalarlo, actualizarlo o utilizarlo. Anthropic no controla los plugins instalados desde marketplaces y no puede verificar que funcionen como se espera ni que no cambien. Consulta la página de cada plugin para obtener más información.",
  "Updated tasks · {done} of {total} done":
    "Tareas actualizadas · {done} de {total} completadas",
  "Bypass all permission checks and let Claudex work uninterrupted in folders you confirm. This works well for workflows like fixing lint errors or generating boilerplate code. Letting Claudex run arbitrary commands is risky and can result in data loss, system corruption, or data exfiltration (e.g., via prompt injection attacks).":
    "Omite todas las comprobaciones de permisos y permite que Claudex trabaje sin interrupciones en las carpetas que confirmes. Es útil para corregir errores de lint o generar código básico. Permitir que Claudex ejecute comandos arbitrarios es arriesgado y puede causar pérdida de datos, daños en el sistema o extracción de datos, por ejemplo mediante ataques de inyección de prompts.",
  "How Claudex structures its responses in Code sessions. Applies to new sessions; the session menu can override it for a single session.":
    "Cómo estructura Claudex sus respuestas en las sesiones de Code. Se aplica a las sesiones nuevas; el menú de la sesión permite cambiarlo para una sola sesión.",
