  "Afternoon, {name}": "Buena tarde, {name}",
  "Career chat": "Charlas sobre carrera profesional",
  "Prepare for an interview": "Preparar una entrevista",
  "Help me prepare for a job interview. I'll share the role and my background, then you ask me likely questions one at a time and give feedback on each answer.":
    "Ayúdame a preparar una entrevista de trabajo. Te contaré el puesto y mi trayectoria, y tú me harás las preguntas probables de una en una y me darás tu opinión sobre cada respuesta.",
  "Sharpen my resume": "Pulir mi currículum",
  "Read my resume, point out what's unclear or missing, then rewrite the weakest parts so my results stand out. Here it is:\n\n":
    "Lee mi currículum, señala lo que no está claro o falta y reescribe las partes más flojas para que destaquen mis logros. Aquí está:\n\n",
  "Rehearse a hard conversation": "Ensayar una conversación difícil",
  "Role-play a conversation I need to have at work. I'll tell you who it's with and what I want to say; you play them realistically, then tell me what worked.":
    "Haz un juego de rol de una conversación que tengo que tener en el trabajo. Te diré con quién es y qué quiero decir; tú interpretas a esa persona con realismo y luego me dices qué funcionó.",
  "Map my next career step": "Trazar mi siguiente paso profesional",
  "Help me plan my next career step. Ask me what I do now, what I enjoy and where I'd like to be, then suggest a few paths and what each would take.":
    "Ayúdame a planificar mi siguiente paso profesional. Pregúntame a qué me dedico ahora, qué me gusta y dónde me gustaría estar, y luego sugiéreme algunos caminos y lo que requeriría cada uno.",
  "Handle a tricky work situation":
    "Gestionar una situación complicada en el trabajo",
  "Help me handle a tricky situation at work: lay out my options and help me pick a next step. Here's what's going on: ":
    "Ayúdame a gestionar una situación complicada en el trabajo: expón mis opciones y ayúdame a elegir el siguiente paso. Esto es lo que pasa: ",
