  "and 1 more": "y 1 más",
  "Automatically archive desktop sessions when the associated pull request is merged or closed. Archiving also removes the session’s worktree and deletes its branch once the pull request is merged. Work that isn’t pushed is kept.":
    "Archivar automáticamente las sesiones de escritorio cuando la pull request asociada se fusiona o se cierra. Una vez fusionada, archivar también quita el worktree de la sesión y elimina su rama. El trabajo que no se haya enviado se conserva.",
  "Archive this session when its pull request is merged or closed. Archiving also removes the session’s worktree and deletes its branch once the pull request is merged. Work that isn’t pushed is kept. This session only; other sessions follow the default in Settings → Claudex Code.":
    "Archivar esta sesión cuando su pull request se fusione o se cierre. Una vez fusionada, archivar también quita el worktree de la sesión y elimina su rama. El trabajo que no se haya enviado se conserva. Solo esta sesión; las demás siguen el valor predeterminado de Ajustes → Claudex Code.",
  "Git won’t check out a branch in two folders at once. Run git worktree list in the repository to see which folder has this branch, switch that folder to a different branch, then try again.":
    "Git no permite tener una rama en dos carpetas a la vez. Ejecuta git worktree list en el repositorio para ver qué carpeta tiene esta rama, cambia esa carpeta a otra rama y vuelve a intentarlo.",
