  "Already installed and open in its own window.":
    "Ya está instalado y abierto en su propia ventana.",
  "This browser isn’t offering to install this artifact here. If you’ve installed it, open it from your desktop or app launcher. If this is a private window, open the page in a regular window.":
    "Este navegador no ofrece la opción de instalar este artefacto aquí. Si ya lo has instalado, ábrelo desde tu escritorio o el lanzador de aplicaciones. Si esta es una ventana privada, abre la página en una ventana normal.",
  "You closed the install dialog. Reload the page to try again.":
    "Has cerrado el cuadro de diálogo de instalación. Vuelve a cargar la página para intentarlo de nuevo.",
  "This browser couldn’t draw the artifact’s icon, and installing needs one. If a privacy setting or extension blocks it, turn that off, or try another browser.":
    "Este navegador no ha podido dibujar el icono del artefacto, y para instalarlo se necesita uno. Si algún ajuste de privacidad o alguna extensión lo bloquea, desactívalo o prueba con otro navegador.",
  "Adding to the Dock needs Safari 17 or later on macOS Sonoma or later.":
    "Para añadir al Dock, necesitas Safari 17 o posterior en macOS Sonoma o posterior.",
  "This browser doesn’t offer to install artifacts. Try Chrome or Edge.":
    "Este navegador no ofrece la opción de instalar artefactos. Prueba con Chrome o Edge.",
  "Tap Share in Safari’s toolbar. If you don’t see it, tap the More button (three dots) first.":
    "Toca Compartir en la barra de herramientas de Safari. Si no lo ves, toca primero el botón Más (tres puntos).",
  "Tap Share in Chrome’s address bar.":
    "Toca Compartir en la barra de direcciones de Chrome.",
  "Open your browser’s menu and tap Share.":
    "Abre el menú del navegador y toca Compartir.",
  "Tap Add to Home Screen. You may need to scroll to find it.":
    "Toca “Añadir a pantalla de inicio”. Es posible que tengas que desplazarte para encontrar esta opción.",
  "Tap Add.": "Toca Añadir.",
  "If you don’t see Add to Home Screen, open this page in Safari and try again.":
    "Si no ves “Añadir a pantalla de inicio”, abre esta página en Safari y vuelve a intentarlo.",
  "Open it from your Home Screen. You may need to sign in again the first time.":
    "Ábrelo desde la pantalla de inicio. Es posible que tengas que volver a iniciar sesión la primera vez.",
  "Tap Chrome’s More button (three dots).":
    "Toca el botón Más opciones de Chrome (tres puntos).",
  "Open your browser’s menu.": "Abre el menú del navegador.",
  "Tap Add to Home screen, then follow the prompts.":
    "Toca “Añadir a pantalla de inicio” y sigue las instrucciones.",
  "In Safari’s menu bar, choose File, then Add to Dock. This needs macOS Sonoma or later.":
    "En la barra de menús de Safari, elige Archivo y, después, Añadir al Dock. Se necesita macOS Sonoma o posterior.",
  "Click Add.": "Haz clic en “Añadir”.",
