    "Convierte esta idea en un diagrama, gráfico o imagen: ",
  "Get this as a document you can edit and share.":
    "Obtén esto como un documento que puedes editar y compartir.",
  "Create a document": "Crear un documento",
  "Turn your last answer into a document I can edit and share. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Convierte tu última respuesta en un documento que pueda editar y compartir. Créalo aquí mismo, en este chat, y hazme como máximo una pregunta. Si falta algo, usa un valor predeterminado razonable y dime qué has supuesto.",
  "Write a document to go with what you just made, and refer to that work by name so the two stay linked. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Escribe un documento que acompañe a lo que acabas de crear y menciona ese trabajo por su nombre para que ambos queden vinculados. Créalo aquí mismo, en este chat, y hazme como mucho una pregunta. Si falta algo, usa un valor predeterminado razonable y dime qué has supuesto.",
  "Get this as a spreadsheet you can sort and update.":
    "Obtén esto como una hoja de cálculo que puedes ordenar y actualizar.",
  "Create a spreadsheet": "Crear una hoja de cálculo",
  "Put the numbers and details from your last answer into a spreadsheet I can sort and update. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Pon los números y detalles de tu última respuesta en una hoja de cálculo que pueda ordenar y actualizar. Créala aquí mismo, en este chat, y hazme como máximo una pregunta. Si falta algo, usa un valor predeterminado razonable y dime qué has supuesto.",
  "Make a spreadsheet to go with what you just made, and refer to that work by name so the two stay linked. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Crea una hoja de cálculo que acompañe a lo que acabas de hacer y refiérete a ese trabajo por su nombre para que ambos queden vinculados. Créala aquí mismo, en este chat, y hazme como mucho una pregunta. Si falta algo, usa un valor predeterminado razonable y dime qué has supuesto.",
  "Get this as a slide deck you can present.":
    "Consigue esto como una presentación de diapositivas que puedes presentar.",
  "Create a slide deck": "Crear una presentación de diapositivas",
  "Turn your last answer into a slide deck I can present. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Convierte tu última respuesta en una presentación de diapositivas que pueda exponer. Créala aquí mismo, en este chat, y hazme como mucho una pregunta. Si falta algo, usa un valor predeterminado razonable y dime qué has supuesto.",
  "Make a slide deck from what you just made, and refer to that work by name so the two stay linked. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Crea una presentación de diapositivas a partir de lo que acabas de hacer, y menciona ese trabajo por su nombre para que ambos queden vinculados. Créala aquí mismo, en este chat, y hazme como máximo una pregunta. Si falta algo, usa un valor predeterminado razonable y dime qué has supuesto.",
  "Get this as a one-page brief for your team.":
    "Obtén esto como un resumen de una página para tu equipo.",
  "Write a brief": "Escribir un informe",
  "Turn your last answer into a one-page brief for my team. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Convierte tu última respuesta en un informe de una página para mi equipo. Créalo aquí mismo, en este chat, y hazme como máximo una pregunta. Si falta algo, usa un valor predeterminado razonable y dime qué has supuesto.",
  "Write a one-page brief that summarizes what you just made, and refer to that work by name so the two stay linked. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Escribe un informe de una página que resuma lo que acabas de crear y refiérete a ese trabajo por su nombre para que ambos queden vinculados. Hazlo aquí mismo, en este chat, y hazme como mucho una pregunta. Si falta algo, usa un valor predeterminado razonable y dime qué has supuesto.",
  "Get this as an email draft, ready to send.":
    "Consigue esto como borrador de correo electrónico, listo para enviar.",
  "Draft an email": "Redactar un correo electrónico",
  "Turn your last answer into an email draft I can send. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Convierte tu última respuesta en un borrador de correo electrónico que pueda enviar. Créalo aquí mismo, en este chat, y hazme como máximo una pregunta. Si falta algo, usa un valor predeterminado razonable y dime qué has supuesto.",
  "Draft an email that shares what you just made, and refer to that work by name so the two stay linked. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Redacta un correo electrónico que comparta lo que acabas de crear, y refiérete a ese trabajo por su nombre para que ambos queden vinculados. Créalo aquí mismo, en este chat, y hazme como máximo una pregunta. Si falta algo, usa un valor predeterminado razonable y dime qué has supuesto.",
  "Get this as a task list you can work through.":
    "Obtén esto como una lista de tareas que puedes ir completando.",
  "Make a task list": "Crear una lista de tareas",
  "Turn your last answer into a task list with clear next steps. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Convierte tu última respuesta en una lista de tareas con pasos siguientes claros. Créala aquí mismo, en este chat, y hazme como máximo una pregunta. Si falta algo, usa un valor predeterminado razonable y dime qué has supuesto.",
  "Make a task list of next actions from what you just made, and refer to that work by name so the two stay linked. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Haz una lista de tareas con las siguientes acciones a partir de lo que acabas de crear, y refiérete a ese trabajo por su nombre para que ambos queden vinculados. Créala aquí mismo, en este chat, y hazme como máximo una pregunta. Si falta algo, usa un valor predeterminado razonable y dime qué has supuesto.",
  "Make this an artifact I can keep editing and share.":
    "Convierte esto en un artefacto que pueda seguir editando y compartir.",
