  "This feature gives Claudex network access to create and analyze files, which has <a>security risks</a>. Monitor chats closely when using this feature.":
    "Esta función da a Claudex acceso a la red para crear y analizar archivos, lo que conlleva <a>riesgos de seguridad</a>. Supervisa de cerca los chats cuando la uses.",
  "Give Claudex network access to install packages and libraries in order to perform advanced data analysis, custom visualizations, and specialized file processing. Monitor chats closely as this comes with <a>security risks</a>.":
    "Da a Claudex acceso a la red para instalar paquetes y bibliotecas y así realizar análisis de datos avanzados, visualizaciones personalizadas y procesamiento de archivos especializado. Supervisa de cerca los chats, ya que esto conlleva <a>riesgos de seguridad</a>.",
