  "Some folders couldn’t be added.": "No se pudieron añadir algunas carpetas.",
  "Bypass all permission checks and let Claudex work uninterrupted. This works well for workflows like fixing lint errors or generating boilerplate code. Letting Claudex run arbitrary commands is risky and can result in data loss, system corruption, or data exfiltration (e.g., via prompt injection attacks).":
    "Omite todas las comprobaciones de permisos y deja que Claudex trabaje sin interrupciones. Esto funciona bien para flujos de trabajo como corregir errores de lint o generar código repetitivo. Permitir que Claudex ejecute comandos arbitrarios es arriesgado y puede provocar pérdida de datos, daños en el sistema o exfiltración de datos (por ejemplo, mediante ataques de inyección de prompts).",
