    "¿En qué se diferencian las URL de los usuarios?",
  "Multiple URLs": "Varias URL",
  "URL pattern": "Patrón de URL",
  "Per-customer URL": "URL por cliente",
  "Users pick from a fixed list of URLs (e.g. regional endpoints).":
    "Los usuarios eligen de una lista fija de URL (por ejemplo, puntos de conexión regionales).",
  "Users enter their own URL matching a regex (e.g. per-tenant subdomain).":
    "Los usuarios introducen su propia URL que coincida con una expresión regular (por ejemplo, un subdominio por inquilino).",
  "Each customer’s URL differs by one part, like a subdomain or org id (e.g. Salesforce My Domain).":
    "La URL de cada cliente difiere en una parte, como un subdominio o ID de organización (por ejemplo, Salesforce My Domain).",
  "Allowed URLs": "URL permitidas",
  "One URL per line.": "Una URL por línea.",
  "URL regex": "Expresión regular de URL",
