  "200 characters or fewer": "200 caracteres o menos",
  "Alternation (|) isn't allowed — use the Multiple URLs option instead":
    "No se permite la alternancia (|); utiliza la opción Varias URL",
  "Avoid nested repetition like (a+)+ — it can hang on long inputs":
    "Evita repeticiones anidadas como (a+)+; pueden bloquearse con entradas largas",
  "Doesn't match the allowed URLs": "No coincide con las URL permitidas",
  "Doesn't match the allowed characters":
    "No coincide con los caracteres permitidos",
  "Lookarounds and backreferences aren't supported — rewrite without (?=, (?!, (?<=, (?<! or \\1-style references":
    "No se admiten aserciones ni referencias inversas; reescribe sin (?=, (?!, (?<=, (?<! ni referencias de tipo \\1",
  "Mark the part each customer fills in, like ${user_config.mydomain}":
    "Marca la parte que completa cada cliente, como ${user_config.mydomain}",
  "Must be 400 characters or fewer": "Debe tener 400 caracteres o menos",
  "Not a valid regular expression": "No es una expresión regular válida",
  "Only the subdomain may vary — end the host with your literal domain, e.g. ^https://[a-z0-9-]+\\.mcp\\.example\\.com/mcp$":
    "Solo puede variar el subdominio; termina el host con tu dominio literal, por ejemplo ^https://[a-z0-9-]+\\.mcp\\.example\\.com/mcp$",
  "Pattern must end with $ so it can't match a longer host":
    "El patrón debe terminar en $ para que no coincida con un host más largo",
  "Pattern must start with ^https://": "El patrón debe comenzar por ^https://",
  "Remove the @ — userinfo before the host isn't allowed":
    "Elimina @; no se permite información de usuario antes del host",
  "Server URL must start with https://":
    "La URL del servidor debe comenzar por https://",
  "The subdomain slot can't use wildcards that match `/`, `.`, `?`, `#` or `@` — use a character class like [a-z0-9-]+ instead of .+ or \\S+":
    "La parte del subdominio no puede usar comodines que coincidan con `/`, `.`, `?`, `#` o `@`; usa una clase como [a-z0-9-]+ en lugar de .+ o \\S+",
  "This field is required": "Este campo es obligatorio",
  "Use one ${user_config.key} only": "Utiliza solo un ${user_config.key}",
  "Edit connector": "Editar conector",
