    "Elimina y vuelve a añadir los conectores para editar los ID de cliente OAuth personalizados.",
  "Delete and re-add connectors to edit custom OAuth Client Secrets.":
    "Elimina y vuelve a añadir los conectores para editar los secretos de cliente OAuth personalizados.",
  "Claudex can’t reach a local address like this one. Enter a public https:// URL.":
    "Claudex no puede acceder a una dirección local como esta. Introduce una URL https:// pública.",
  "Turn on computer use?": "¿Activar el uso del ordenador?",
  "Grant macOS permissions": "Conceder permisos de macOS",
  "Keep in mind:": "Ten en cuenta:",
  "Some actions can’t be undone.": "Algunas acciones no se pueden deshacer.",
