  "Read safe use tips": "Leer consejos de uso seguro",
  "Computer use is on. To finish setup, grant the macOS permissions below.":
    "El uso del ordenador está activado. Para terminar, concede los permisos de macOS de abajo.",
  Denied: "Denegado",
  "Not requested": "No solicitado",
  "Background computer use": "Uso del ordenador en segundo plano",
  "Claudex will see your whole screen and use your mouse and keyboard on it. You’ll approve the apps Claudex asks for, but on this system access can’t be limited to them, and you won’t confirm each step Claudex performs.":
    "Claudex verá toda tu pantalla y usará el ratón y el teclado. Aprobarás las apps que pida, pero en este sistema el acceso no puede limitarse a ellas y no confirmarás cada paso.",
  "Claudex will see the apps you approve and click and type in them, working in the background while you keep using your computer or taking full control of your screen. Which of those Claudex does by default is set under Settings → This computer → Computer use. You’ll approve each app, but not confirm each step Claudex performs.":
    "Claudex verá las apps que apruebes y hará clic y escribirá en ellas, en segundo plano mientras sigues usando el ordenador o con control total de la pantalla. Lo que hace por defecto se configura en Ajustes → Este ordenador → Uso del ordenador. Aprobarás cada app, pero no confirmarás cada paso.",
  "Claudex can now control your applications in the background without taking over your screen, and will ask your permission if Claudex needs full control of your mouse and keyboard. If you’d prefer Claudex to default to full control instead of background mode, you can change this at any time under Settings → This computer → Computer use.":
    "Claudex ahora puede controlar tus aplicaciones en segundo plano sin ocupar la pantalla, y te pedirá permiso si necesita el control total del ratón y el teclado. Si prefieres que use el control total por defecto, puedes cambiarlo cuando quieras en Ajustes → Este ordenador → Uso del ordenador.",
