  "Claudex will browse and interact with any website without asking. Applies to new sessions. This setting can put your data at risk.":
    "Claudex navegará e interactuará con cualquier sitio web sin preguntar. Se aplica a las nuevas sesiones. Esta configuración puede poner en riesgo tus datos.",
