  "Browser default": "Voz predeterminada del navegador",
  "Local sessions stay on this computer. Cloud sessions and synced data are stored by your Claudex service. Each model provider's data policies apply to requests it receives.":
    "Las sesiones locales permanecen en este ordenador. Tu servicio de Claudex almacena las sesiones en la nube y los datos sincronizados. Cada proveedor de modelos aplica sus políticas de datos a las solicitudes que recibe.",
  "Local sessions are stored on this computer. Cloud chats, projects and files are stored by your Claudex service.":
    "Las sesiones locales se guardan en este ordenador. Tu servicio de Claudex almacena los chats, proyectos y archivos en la nube.",
  "When your service supports reporting, Preferences below controls whether diagnostic and reply-feedback reports are sent.":
    "Si tu servicio admite los informes, las preferencias de abajo controlan si se envían diagnósticos y comentarios sobre las respuestas.",
  "You can manage your shared chats and artifacts below when sharing is available.":
    "Cuando esté disponible la función de compartir, puedes gestionar abajo los chats y artefactos compartidos.",
  "Your messages and attached content are sent to the model provider used for that session. That provider's data policies apply.":
    "Tus mensajes y el contenido adjunto se envían al proveedor de modelos utilizado en esa sesión. Se aplican sus políticas de datos.",
  "Optional diagnostic reports contain error codes and known error descriptions, not prompts, replies or file paths.":
    "Los informes de diagnóstico opcionales contienen códigos y descripciones de errores conocidos, sin instrucciones, respuestas ni rutas de archivos.",
  "Reply feedback can include your rating, selected categories and comment. A conversation excerpt is included only when your service allows it and you choose to include it.":
    "Los comentarios sobre las respuestas pueden incluir tu valoración, las categorías seleccionadas y tu comentario. Solo se incluye un extracto de la conversación si tu servicio lo permite y tú lo eliges.",
  "Claudex does not set your model provider's training or retention policy.":
    "Claudex no establece las políticas de entrenamiento ni de conservación de datos de tu proveedor de modelos.",
