  "Search by name": "Buscar por nombre",
  "Build connectors and plugins": "Crear conectores y plugins",
  "A connector is an MCP server: it speaks the Model Context Protocol over streamable HTTP, signs people in with OAuth or a token, and describes each tool’s inputs and effects plainly. A plugin bundles skills, connectors and instructions into one package. Add your connector as a custom connector under Customize → Connectors and try it in a chat before you send it with Submit to the directory.":
    "Un conector es un servidor MCP: habla el Model Context Protocol sobre HTTP en streaming, inicia sesión con OAuth o un token y describe con claridad las entradas y los efectos de cada herramienta. Un plugin reúne skills, conectores e instrucciones en un solo paquete. Añade tu conector como conector personalizado en Personalizar → Conectores y pruébalo en un chat antes de enviarlo con Enviar al directorio.",
